"""
site_archive_aws – PyEarthTools data accessors for Met Office datasets on AWS ASDI.

Available accessors
-------------------

.. list-table::
   :header-rows: 1
   :widths: 25 55 20

   * - Class
     - Description
     - Temporal resolution
   * - :class:`~site_archive_aws.mo_global_10km.MOGlobal10km`
     - Met Office Global 10 km Deterministic NWP
     - 6-hourly
   * - :class:`~site_archive_aws.mo_ukv.MOUKV`
     - Met Office UKV (~1.5 km) model
     - Hourly
   * - :class:`~site_archive_aws.mogreps_global.MOGREPSGlobal`
     - MOGREPS-G 18-member global ensemble
     - 6-hourly
   * - :class:`~site_archive_aws.mogreps_uk.MOGREPSUK`
     - MOGREPS-UK 18-member regional ensemble
     - 3-hourly

Quick start::

    import site_archive_aws

    # Load 2-m temperature from the Global 10km model
    accessor = site_archive_aws.MOGlobal10km("2t", anon=True)
    ds = accessor["2023-06-01T00:00"]
    print(ds)

Configuration
-------------
S3 bucket roots are read from ``~/.pyearthtoolsconfig`` under the ``[aws]``
section.  If not set, the public default buckets are used.
"""

import os

from pyearthtools.data.archive import (
    register_archive,
    load_root_directories_from_config,
)

# ---------------------------------------------------------------------------
# Default S3 root directory mapping.
# These defaults point at the public Met Office ASDI buckets.
# Override in ~/.pyearthtoolsconfig under [aws].
# ---------------------------------------------------------------------------

ROOT_DIRECTORIES = {
    "MOGlobal10km": "s3://met-office-atmospheric-model-data/global-deterministic/",
    "MOUKV_AWS":    "s3://met-office-atmospheric-model-data/uk-deterministic/",
    "MOGREPSGlobal": "s3://met-office-ensemble-model-data/global-ensemble/",
    "MOGREPSUK":    "s3://met-office-ensemble-model-data/uk-ensemble/",
}

register_archive("ROOT_DIRECTORIES")(ROOT_DIRECTORIES)

# Make 'aws' a registered archive namespace so pyearthtools can find it
import site_archive_aws  # noqa: E402

from site_archive_aws.mo_global_10km import MOGlobal10km  # noqa: E402, F401
from site_archive_aws.mo_ukv import MOUKV  # noqa: E402, F401
from site_archive_aws.mogreps_global import MOGREPSGlobal  # noqa: E402, F401
from site_archive_aws.mogreps_uk import MOGREPSUK  # noqa: E402, F401

register_archive("aws")(site_archive_aws)

# Load user-specific overrides from the PyEarthTools config file
config_path = os.path.expanduser("~/.pyearthtoolsconfig")
load_root_directories_from_config(config_path=config_path)

try:
    # Generated by setuptools-scm at install time; not in version control.
    from ._version import __version__  # type: ignore
except ImportError:
    __version__ = "999"

__all__ = [
    "MOGlobal10km",
    "MOUKV",
    "MOGREPSGlobal",
    "MOGREPSUK",
]

